-- drop_data：<1.12.0 全部迁移的最终状态 dump（schema + 种子数据）
CREATE TABLE `drop_data`
(
    `id` INTEGER PRIMARY KEY AUTOINCREMENT,
    `dropperid`        INT(11)    NOT NULL,
    `itemid`           INT(11)    NOT NULL DEFAULT '0',
    `minimum_quantity` INT(11)    NOT NULL DEFAULT '1',
    `maximum_quantity` INT(11)    NOT NULL DEFAULT '1',
    `questid`          INT(11)    NOT NULL DEFAULT '0',
    `chance`           INT(11)    NOT NULL DEFAULT '0'

);
CREATE INDEX `drop_data_idx3` ON `drop_data` (dropperid, itemid);
CREATE INDEX `drop_data_mobid` ON `drop_data` (`dropperid`);
CREATE UNIQUE INDEX `drop_data_uq1` ON `drop_data` (`dropperid`, `itemid`);
